impl CryptoLimits {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"ciphers\":");
		out.push('[');
		let mut v24 = true;
		for v23 in self.ciphers.iter() {
			if !v24 {
				out.push(',');
			}
			v24 = false;
			v23.to_json_into(out);
		}
		out.push(']');
		out.push(',');
		out.push_str("\"max-key-len\":");
		let _ = write!(out, "{}", self.max_key_len);
		out.push(',');
		out.push_str("\"max-request\":");
		let _ = write!(out, "{}", self.max_request);
		out.push(',');
		out.push_str("\"max-sessions\":");
		let _ = write!(out, "{}", self.max_sessions);
		out.push('}');
	}
	pub fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("ciphers=");
		out.push('[');
		let mut v26 = true;
		for v25 in self.ciphers.iter() {
			if !v26 {
				out.push_str(", ");
			}
			v26 = false;
			v25.to_text_into(out);
		}
		out.push(']');
		out.push_str(", ");
		out.push_str("max-key-len=");
		let _ = write!(out, "{}", self.max_key_len);
		out.push_str(", ");
		out.push_str("max-request=");
		let _ = write!(out, "{}", self.max_request);
		out.push_str(", ");
		out.push_str("max-sessions=");
		let _ = write!(out, "{}", self.max_sessions);
		out.push('}');
	}
	pub fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 4);
		crate::codec::cbor::text(out, "ciphers");
		crate::codec::cbor::array(out, self.ciphers.len());
		for v27 in self.ciphers.iter() {
			v27.to_cbor_into(out);
		}
		crate::codec::cbor::text(out, "max-key-len");
		crate::codec::cbor::uint(out, self.max_key_len as u64);
		crate::codec::cbor::text(out, "max-request");
		crate::codec::cbor::uint(out, self.max_request as u64);
		crate::codec::cbor::text(out, "max-sessions");
		crate::codec::cbor::uint(out, self.max_sessions as u64);
	}
}

